// src/mini-apps/asset-studio/document-markdown.ts
function assetDocumentHasContent(document2) {
  return Boolean(document2?.sections.some((section) => section.summary.trim() || section.blocks.some((block2) => {
    switch (block2.kind) {
      case "prose":
        return Boolean(block2.markdown.trim());
      case "list":
        return block2.items.some((item) => item.trim());
      case "checklist":
        return block2.items.some((item) => item.label.trim() || item.detail.trim());
      case "table":
        return block2.rows.some((row) => row.some((cell) => cell.trim()));
      case "callout":
        return Boolean(block2.body.trim());
      case "image":
        return Boolean(block2.assetReferenceId.trim());
      case "page_break":
        return false;
    }
  })));
}
function assetDocumentMarkdown(document2) {
  const cell = (value) => value.replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
  const block2 = (value) => {
    let text4 = "";
    switch (value.kind) {
      case "prose":
        text4 = value.markdown;
        break;
      case "list":
        text4 = value.items.map((item, i2) => `${value.style === "numbered" ? `${i2 + 1}.` : "-"} ${item}`).join("\n");
        break;
      case "checklist":
        text4 = value.items.map((item) => `- [ ] ${item.label}${item.detail ? ` \u2014 ${item.detail}` : ""}`).join("\n");
        break;
      case "callout":
        text4 = `> **${value.title}**
> ${value.body.replace(/\n/g, "\n> ")}`;
        break;
      case "table":
        text4 = [`| ${value.columns.map(cell).join(" | ")} |`, `| ${value.columns.map(() => "---").join(" | ")} |`, ...value.rows.map((row) => `| ${row.map(cell).join(" | ")} |`)].join("\n");
        break;
      case "image":
        return `*H\xECnh \u1EA3nh: ${value.altText}${value.caption ? ` \u2014 ${value.caption}` : ""} (tham chi\u1EBFu ${value.assetReferenceId}; xem b\u1EA3n g\u1ED1c trong Asset Studio).*`;
      case "page_break":
        return "---";
    }
    const pending = value.claims.filter((claim2) => claim2.status === "needs_review");
    return text4 + (pending.length ? "\n\n> **C\u1EA7n ki\u1EC3m tra trong b\u1EA3n ngu\u1ED3n:**\n" + pending.map((claim2) => `> - ${claim2.text}${claim2.note ? ` \u2014 ${claim2.note}` : ""}`).join("\n") : "");
  };
  return [`# ${document2.title}`, document2.subtitle, ...document2.sections.map((section) => [`## ${section.title}`, section.summary, ...section.blocks.map(block2)].filter(Boolean).join("\n\n"))].filter(Boolean).join("\n\n");
}

// src/mini-apps/sdk/image-format.ts
function detectImageAsset(data) {
  const bytes = Buffer.from(data);
  if (bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) return { mimeType: "image/png", extension: "png" };
  if (bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255) return { mimeType: "image/jpeg", extension: "jpg" };
  if (bytes.subarray(0, 4).toString() === "RIFF" && bytes.subarray(8, 12).toString() === "WEBP") return { mimeType: "image/webp", extension: "webp" };
  if (["GIF87a", "GIF89a"].includes(bytes.subarray(0, 6).toString())) return { mimeType: "image/gif", extension: "gif" };
  throw new Error("Images must be PNG, JPEG, WebP, or GIF");
}

